// Parse real-time GitHub events stream for WatchEvents (Stars) with deduplication
const items = $input.all();
const config = $('Config & Credentials').first().json;
const staticData = $getWorkflowStaticData('global');
const lastProcessedTime = staticData.lastStarredAt ? new Date(staticData.lastStarredAt) : null;

let stars = [];

for (const item of items) {
  const data = Array.isArray(item.json) ? item.json : (item.json.data || [item.json]);
  for (const entry of data) {
    if (entry.type === 'WatchEvent') {
      stars.push({
        username: entry.actor.login,
        user_id: entry.actor.id,
        avatar_url: entry.actor.avatar_url,
        starred_at: entry.created_at
      });
    } else if (entry.user && entry.starred_at) {
      stars.push({
        username: entry.user.login,
        user_id: entry.user.id,
        avatar_url: entry.user.avatar_url,
        starred_at: entry.starred_at
      });
    }
  }
}

if (stars.length === 0) {
  return [];
}

// Sort chronological
stars.sort((a, b) => new Date(a.starred_at) - new Date(b.starred_at));

const newLeads = [];
let maxStarredAt = lastProcessedTime;

for (const star of stars) {
  const starDate = new Date(star.starred_at);
  if (!lastProcessedTime || starDate > lastProcessedTime) {
    newLeads.push({
      json: {
        username: star.username,
        user_id: star.user_id,
        avatar_url: star.avatar_url,
        starred_at: star.starred_at,
        repo: config.REPO_OWNER + '/' + config.REPO_NAME
      }
    });
    if (!maxStarredAt || starDate > maxStarredAt) {
      maxStarredAt = starDate;
    }
  }
}

if (maxStarredAt) {
  staticData.lastStarredAt = maxStarredAt.toISOString();
}

// Fallback for immediate test execution if all events were already marked seen
if (newLeads.length === 0 && stars.length > 0) {
  const latest = stars[stars.length - 1];
  return [{
    json: {
      username: latest.username,
      user_id: latest.user_id,
      avatar_url: latest.avatar_url,
      starred_at: latest.starred_at,
      repo: config.REPO_OWNER + '/' + config.REPO_NAME,
      is_test_replay: true
    }
  }];
}

return newLeads;

