// Combine enriched profile data with the generated Gemini sales pitch
const profile = $('Filter: High-Value Lead?').first().json;
const geminiResponse = $input.first().json;
const config = $('Config & Credentials').first().json;

let pitch = 'High-potential lead with strong open-source presence; ideal candidate for developer partnership.';

try {
  const candidateText = geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text;
  if (candidateText) {
    pitch = candidateText.trim().replace(/^[\"']|[\"']$/g, '');
  }
} catch (err) {
  // Keep fallback pitch
}

// Format payload as rich Discord embed
const discordPayload = {
  username: 'Lead Sniper Bot',
  avatar_url: 'https://github.githubassets.com/images/modules/logos_page/GitHub-Mark.png',
  embeds: [
    {
      title: '🎯 High-Value Lead Detected: ' + (profile.name || profile.login),
      url: profile.html_url,
      color: 5763719,
      thumbnail: {
        url: profile.avatar_url
      },
      fields: [
        {
          name: '👤 User',
          value: '[**' + (profile.name || profile.login) + '** (@' + profile.login + ')](' + profile.html_url + ')',
          inline: true
        },
        {
          name: '🏢 Company',
          value: profile.company || 'Not specified',
          inline: true
        },
        {
          name: '📍 Location',
          value: profile.location || 'Not specified',
          inline: true
        },
        {
          name: '👥 Followers',
          value: '**' + (profile.followers || 0).toLocaleString() + '**',
          inline: true
        },
        {
          name: '📦 Public Repos',
          value: '**' + (profile.public_repos || 0).toLocaleString() + '**',
          inline: true
        },
        {
          name: '⭐ Starred Repo',
          value: '`' + config.REPO_OWNER + '/' + config.REPO_NAME + '`',
          inline: true
        },
        {
          name: '📝 Bio',
          value: profile.bio ? ('*"' + profile.bio + '"*') : '_No bio provided._',
          inline: false
        },
        {
          name: '💡 AI Sales Pitch',
          value: '>>> **' + pitch + '**',
          inline: false
        }
      ],
      footer: {
        text: 'Lead Sniper • GitHub Ingestion & Enrichment Pipeline'
      },
      timestamp: new Date().toISOString()
    }
  ]
};

return [{
  json: {
    discord_payload: discordPayload,
    lead_login: profile.login,
    lead_name: profile.name,
    sales_pitch: pitch
  }
}];
